def fib(n):
    if n <= 1:
        return n
    prev2, prev1 = 0, 1
    for _ in range(2, n + 1):
        prev2, prev1 = prev1, prev1 + prev2
    return prev1

# Example: fib(10) -> 55
# Time: O(n), Space: O(1). Rolling variables replace the full DP table.

def climb_stairs(n):
    if n <= 2:
        return n
    prev2, prev1 = 1, 2
    for _ in range(3, n + 1):
        prev2, prev1 = prev1, prev1 + prev2
    return prev1

# Example: climb_stairs(3) -> 3
# Time: O(n), Space: O(1). Fibonacci-style rolling DP.

def coin_change(coins, amount):
    INF = float('inf')
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] != INF:
                dp[a] = min(dp[a], dp[a - c] + 1)
    return dp[amount] if dp[amount] != INF else -1

# Example: coin_change([1,2,5], 11) -> 3
# Time: O(amount * len(coins)), Space: O(amount). Unbounded knapsack minimum coin DP.

def knapsack(weights, values, capacity):
    dp = [0] * (capacity + 1)
    for i in range(len(weights)):
        w, v = weights[i], values[i]
        for cap in range(capacity, w - 1, -1):
            dp[cap] = max(dp[cap], dp[cap - w] + v)
    return dp[capacity]

# Example: knapsack([1,3,4,5],[1,4,5,7], 7) -> 9
# Time: O(n*W), Space: O(W). 1D DP iterating capacity backwards to avoid reuse.

def longest_palindromic_subsequence(s):
    n = len(s)
    dp = [1] * n
    for i in range(n - 2, -1, -1):
        prev = 0
        for j in range(i + 1, n):
            temp = dp[j]
            if s[i] == s[j]:
                dp[j] = prev + 2
            else:
                dp[j] = max(dp[j], dp[j - 1])
            prev = temp
    return dp[n - 1] if n > 0 else 0

# Example: longest_palindromic_subsequence('bbbab') -> 4
# Time: O(n^2), Space: O(n). Interval DP on reversed ends with rolling 1D row.

import bisect

def length_of_lis(nums):
    tails = []
    for num in nums:
        i = bisect.bisect_left(tails, num)
        if i == len(tails):
            tails.append(num)
        else:
            tails[i] = num
    return len(tails)

# Example: length_of_lis([10,9,2,5,3,7,101,18]) -> 4
# Time: O(n log n), Space: O(n). Patience sorting with binary search over tails.

def longest_common_subsequence(s1, s2):
    m, n = len(s1), len(s2)
    dp = [0] * (n + 1)
    for i in range(1, m + 1):
        prev = 0
        for j in range(1, n + 1):
            temp = dp[j]
            if s1[i-1] == s2[j-1]:
                dp[j] = prev + 1
            else:
