def count_subsets_sum(nums, target):
    dp = [0] * (target + 1)
    dp[0] = 1
    for num in nums:
        for t in range(target, num - 1, -1):
            dp[t] += dp[t - num]
    return dp[target]

# Example: count_subsets_sum([1,2,3], 4) -> 1  ([1,3] is the only subset summing to 4)
