def rod_cutting(prices, n):
    dp = [0] * (n + 1)
    for length in range(1, n + 1):
        best = prices[length - 1] if length <= len(prices) else 0
        for cut in range(1, length):
            best = max(best, dp[cut] + dp[length - cut])
        dp[length] = best
    return dp[n]

# Example: rod_cutting([1,5,8,9,10,17,17,20], 8) -> 22
# Time: O(n^2), Space: O(n). Unbounded 1D knapsack over rod lengths.

def count_coin_combinations(coins, target):
    dp = [0] * (target + 1)
    dp[0] = 1
    for coin in coins:
        for t in range(coin, target + 1):
            dp[t] += dp[t - coin]
    return dp[target]

# Example: count_coin_combinations([1,2,5], 5) -> 4
