def min_cut_palindrome_partition(s):
    n = len(s)
    is_pal = [[False] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            if s[i] == s[j] and (j - i <= 2 or is_pal[i+1][j-1]):
                is_pal[i][j] = True
    cuts = [0] * n
    for i in range(n):
        if is_pal[0][i]:
            cuts[i] = 0
            continue
        best = i
        for j in range(i):
            if is_pal[j+1][i]:
                best = min(best, cuts[j] + 1)
        cuts[i] = best
    return cuts[n - 1]

# Example: min_cut_palindrome_partition('aab') -> 1
# Time: O(n^2), Space: O(n^2). Precompute palindrome table then min-cut DP.

def can_jump(nums):
    farthest = 0
    for i, num in enumerate(nums):
        if i > farthest:
            return False
        farthest = max(farthest, i + num)
    return True

# Example: can_jump([2,3,1,1,4]) -> True
# Time: O(n), Space: O(1). Track the farthest reachable index as you scan.

